- Track: { TrackId (int), Name (str), AlbumId (int), MediaTypeId (int), GenreId (int), Composer (str, nullable), Milliseconds (int), Bytes (int), UnitPrice (float) }

college_1:
- CLASS: { CLASS_CODE (str), CRS_CODE (str), CLASS_SECTION (str), CLASS_TIME (str), CLASS_ROOM (str), PROF_NUM (int) }
- COURSE: { CRS_CODE (str), DEPT_CODE (str), CRS_DESCRIPTION (str), CRS_CREDIT (float) }
